const listInfectionAlertRules = `-- name: ListInfectionAlertRules :many
SELECT rule_id, tenant_id, code, name, revision, organisms, lookback_days, precaution, advice, approved, approved_by, approved_at, effective_from, superseded_at, created_at, created_by FROM infection.alert_rule
WHERE tenant_id = $1
  AND ($2::text = '' OR code = $2)
  AND (NOT $3::boolean
       OR (approved
           AND effective_from IS NOT NULL AND effective_from <= $4
           AND (superseded_at IS NULL OR superseded_at > $4)))
ORDER BY code, revision DESC
`

type ListInfectionAlertRulesParams struct {
	TenantID uuid.UUID
	Code     string
	LiveOnly bool
	At       pgtype.Timestamptz
}

func (q *Queries) ListInfectionAlertRules(ctx context.Context, arg ListInfectionAlertRulesParams) ([]InfectionAlertRule, error) {
	rows, err := q.db.Query(ctx, listInfectionAlertRules,
		arg.TenantID,
		arg.Code,
		arg.LiveOnly,
		arg.At,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InfectionAlertRule{}
	for rows.Next() {
		var i InfectionAlertRule
		if err := rows.Scan(
			&i.RuleID,
			&i.TenantID,
			&i.Code,
			&i.Name,
			&i.Revision,
			&i.Organisms,
			&i.LookbackDays,
			&i.Precaution,
			&i.Advice,
			&i.Approved,
			&i.ApprovedBy,
			&i.ApprovedAt,
			&i.EffectiveFrom,
			&i.SupersededAt,
			&i.CreatedAt,
			&i.CreatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

