const listInfectionStewardshipRules = `-- name: ListInfectionStewardshipRules :many
SELECT rule_id, tenant_id, code, name, revision, kind, agents, all_agents, day_threshold, prompt, approved, approved_by, approved_at, effective_from, superseded_at, created_at, created_by FROM infection.stewardship_rule
WHERE tenant_id = $1
  AND ($2::text = '' OR code = $2)
  AND (NOT $3::boolean
       OR (approved
           AND effective_from IS NOT NULL AND effective_from <= $4
           AND (superseded_at IS NULL OR superseded_at > $4)))
ORDER BY code, revision DESC
`

type ListInfectionStewardshipRulesParams struct {
	TenantID uuid.UUID
	Code     string
	LiveOnly bool
	At       pgtype.Timestamptz
}

func (q *Queries) ListInfectionStewardshipRules(ctx context.Context, arg ListInfectionStewardshipRulesParams) ([]InfectionStewardshipRule, error) {
	rows, err := q.db.Query(ctx, listInfectionStewardshipRules,
		arg.TenantID,
		arg.Code,
		arg.LiveOnly,
		arg.At,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InfectionStewardshipRule{}
	for rows.Next() {
		var i InfectionStewardshipRule
		if err := rows.Scan(
			&i.RuleID,
			&i.TenantID,
			&i.Code,
			&i.Name,
			&i.Revision,
			&i.Kind,
			&i.Agents,
			&i.AllAgents,
			&i.DayThreshold,
			&i.Prompt,
			&i.Approved,
			&i.ApprovedBy,
			&i.ApprovedAt,
			&i.EffectiveFrom,
			&i.SupersededAt,
			&i.CreatedAt,
			&i.CreatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

